"""Record post-review source readings and explicit editorial-state comparisons.

This is a reproducible dossier, not automatic transcription or an identity model.
"""
import hashlib,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3]
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def dump(p,x):p.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
def main():
 receipts=json.loads((ROOT/'research/independent_pass/text/highres_receipts.json').read_text())
 caps={r['capture_index']:r['capture'] for r in receipts if r['id']=='20274' and r.get('saved')}
 annotations=[]
 specs=[('T-20274-invitatory',0,[880,900,900,330],'Recolentes xpm passum et','Recolentes Christum passum et','Christum is a proposed expansion of the visible barred christogram. No separate pium is visible between it and passum under that expansion. This is a provisional reading, not a gold transcription.'),('T-20274-order',1,[80,100,1590,310],'Matri sue con / do lentes procida[...]','Matri sue condolentes [before] procidamus','The line wraps within condolentes; Matri begins before the procida- word. Full syllabic underlay and abbreviation expansion remain provisional. Comparison concerns word order, not manuscript identity.'),('T-20274-transition',1,[80,400,1580,250],'alleluya; ps; Venite; [red rubric]; Immolandus ligna gerit','Psalm Venite then nocturn rubric and Immolandus','No intervening hymn entry is visible in this continuous region. This is an observation about this written book, not a claim that the hymn was omitted in performance or absent elsewhere.')]
 for ident,index,region,literal,normalized,body in specs:
  c=caps[index];annotations.append({'id':ident,'type':'Annotation','motivation':'describing','fragment_id':'mpo-20274','body':{'type':'TextualBody','value':body,'language':'en'},'target':{'source':c['path'],'selector':{'type':'FragmentSelector','conformsTo':'http://www.w3.org/TR/media-frags/','value':'xywh='+','.join(map(str,region))}},'source_url':c['url'],'sha256':c['sha256'],'image_dimensions':[c['width'],c['height']],'observer':'Codex AI source reading,2026-10-22; exact model/checkpoint not exposed','evidence_kind':'image reading compared with published apparatus','verification':'Provisional AI source reading; no independent expert adjudication','interpretation_limits':['Edited text and reported manuscript states are separate sources.','No identity, melodic or performance inference from common text/omission.','No independent expert label, blind test or rare-variant claim.'],'reading':{'literal_candidate':literal,'normalized_search_text':normalized,'certainty':'provisional; expansion and music-underlay spacing are explicit','external_references':['https://lup.lub.lu.se/student-papers/record/9032430/file/9032431.pdf#page=53','https://lup.lub.lu.se/student-papers/record/9032430/file/9032431.pdf#page=67']}})
 tests=[{'id':'TC01','observation_id':specs[0][0],'question':'Does source agreement with edited C435 identify agreement with the reported unedited witness at the invitatory?','target':'No separate pium visible under usual christogram expansion.','edited_C435':'omits pium','reported_C435_manuscript':'includes pium, apparatus line171 and C23 apparatus line742','C23_edition':'omits pium','reference_pdf_pages':[52,67],'outcome':'Edited-text agreement hides a reported manuscript-state difference. No physical identity or transmission branch established.'},{'id':'TC02','observation_id':specs[1][0],'question':'Does the visible phrase order distinguish the reported states?','target':'Matri...condolentes before procida...','edited_C435':'same standard order','reported_C435_manuscript':'procidamus congementes precedes matri sue condolentes, as reported in the apparatus','C23_edition':'Matri...condolentes before procidamus congementes','reference_pdf_pages':[52,67],'outcome':'Provisional source order agrees with the standard/edited order, while differing from the reported C435 manuscript state. This is not a distinctive C23 fingerprint.'},{'id':'TC03','observation_id':specs[2][0],'question':'Can the edition hymn entry or melody be silently supplied to this source?','target':'Visible transition from invitatory/psalm to nocturn antiphon without an intervening hymn entry.','C435_edition':'Rogatus Deus rumpere at this position','C23_edition':'O rosa fragrantissima at this position','reference_pdf_pages':[52,53,67],'outcome':'No. Written contents differ in scope; book function, abbreviations or a hymn supplied elsewhere are alternatives. No liturgical-performance omission inferred.'}]
 result={'version':'2.0.0','assessment_date':'2026-10-22','scope':'Post-review descriptive apparatus-aware source comparison, not a new classifier','reference':{'path':'research/scholarship/hallqvist2020.pdf','sha256':sha(ROOT/'research/scholarship/hallqvist2020.pdf'),'url':'https://lup.lub.lu.se/student-papers/record/9032430/file/9032431.pdf','printed_pages':['v–ix','5–6','20'],'pdf_pages':[10,11,12,13,14,52,53,67],'checked':'relevant complete pages extracted and visually inspected; C435 original photographs not inspected'},'tests':tests,'source_observation_ids':[x[0] for x in specs],'new_identity_signal_established':False,'new_discovery':False,'independent_expert_review':False,'limits':['The reported manuscript readings are editorial assertions, not our inspection of C435/C23 originals.','Negative apparatus does not license silent reconstruction of every unlisted witness.','No rarity/frequency, transmission stemma, new manuscript relation or melodic variant established.','All readings/tests selected after prior review; no new untouched evaluation.']}
 dump(ROOT/'data/text_collation.v2.json',result)
 dump(Path(__file__).with_name('observations.json'),{'@context':'http://www.w3.org/ns/anno.jsonld','version':'1.0.0','annotations':annotations})
 print(json.dumps({'source_regions':len(annotations),'comparisons':len(tests),'identity_signal':False}))
if __name__=='__main__':main()
